<script setup lang="ts">
import { computed } from 'vue'; import { useRoute } from 'vue-router'; import AppStatusChip from '@/Components/AppStatusChip.vue'; import PageHeader from '@/Components/layout/PageHeader.vue'; import { useAdministratorStore } from '@/stores/administrator.store'
const route = useRoute(); const store = useAdministratorStore(); const mission = computed(() => store.getMissionById(route.params.missionId as string)); const site = computed(() => mission.value ? store.getSiteById(mission.value.siteId) : undefined); const supervisor = computed(() => mission.value ? store.getUserById(mission.value.supervisorId) : undefined); const leader = computed(() => mission.value ? store.getUserById(mission.value.teamLeaderId) : undefined); const agents = computed(() => mission.value?.agentIds.map((id) => store.getUserById(id)).filter(Boolean) ?? []); const formatDate = (value: string) => new Intl.DateTimeFormat('fr-FR', { dateStyle: 'full', timeStyle: 'short' }).format(new Date(value))
</script>
<template><div class="mx-auto w-full max-w-[1100px]"><PageHeader><template #title>{{ mission?.title ?? 'Mission introuvable' }}</template><template #description>Organisation, équipe affectée et état d’exécution.</template><template #actions><v-btn variant="outlined" prepend-icon="mdi-arrow-left" :to="{ name: 'admin-missions' }">Retour</v-btn><v-btn v-if="mission" color="primary" prepend-icon="mdi-pencil-outline" :to="{ name: 'admin-mission-edit', params: { missionId: mission.id } }">Modifier</v-btn></template></PageHeader><v-alert v-if="!mission" type="error" variant="tonal" title="Mission introuvable" /><div v-else class="grid gap-6 lg:grid-cols-[1.25fr_0.75fr]"><div class="space-y-6"><v-card><v-card-title class="flex items-center justify-between px-6 py-5"><span>Déroulement</span><AppStatusChip :status="mission.status" /></v-card-title><v-divider /><v-card-text class="grid gap-5 px-6 py-6 sm:grid-cols-2"><div><p class="text-xs text-[#848484]">Site</p><p class="mt-1 font-medium">{{ site?.name ?? 'Site inconnu' }}</p></div><div><p class="text-xs text-[#848484]">Équipe</p><p class="mt-1 font-medium">{{ mission.teamName }}</p></div><div><p class="text-xs text-[#848484]">Début</p><p class="mt-1 font-medium">{{ formatDate(mission.startAt) }}</p></div><div><p class="text-xs text-[#848484]">Fin</p><p class="mt-1 font-medium">{{ formatDate(mission.endAt) }}</p></div><div class="sm:col-span-2"><p class="text-xs text-[#848484]">Instructions</p><p class="mt-1 text-sm leading-6">{{ mission.notes || 'Aucune instruction.' }}</p></div></v-card-text></v-card><v-card><v-card-title class="px-6 py-5">Agents affectés</v-card-title><v-divider /><v-list><v-list-item v-for="agent in agents" :key="agent?.id" :title="`${agent?.firstName} ${agent?.lastName}`" :subtitle="agent?.employeeNumber" prepend-icon="mdi-account-outline" /></v-list></v-card></div><v-card class="h-fit"><v-card-title class="px-5 py-5">Encadrement</v-card-title><v-divider /><v-list lines="two"><v-list-item prepend-icon="mdi-account-tie-outline" title="Superviseur" :subtitle="supervisor ? `${supervisor.firstName} ${supervisor.lastName}` : 'Non affecté'" /><v-list-item prepend-icon="mdi-account-star-outline" title="Chef d’équipe" :subtitle="leader ? `${leader.firstName} ${leader.lastName}` : 'Non affecté'" /></v-list><v-divider /><v-card-actions v-if="!['completed','cancelled'].includes(mission.status)" class="pa-5"><v-btn block variant="tonal" color="error" prepend-icon="mdi-close-circle-outline" @click="store.cancelMission(mission.id)">Annuler la mission</v-btn></v-card-actions></v-card></div></div></template>
